    "about3.whatwedo.eyebrow": "私たちの仕事",
    "about3.whatwedo.title": "フルスタックで、最初から最後まで",
    "about3.whatwedo.p1": "TechnovoraはAI自動化、ウェブ・モバイル開発、クラウドインフラ、デザインをカバーするフルスタックのエンジニアリングパートナーです。5つの異なるベンダーをつなぎ合わせる必要はありません。",
    "about3.whatwedo.p2": "自律型AIエージェントから、スケールとスピードのために設計された本番グレードのプラットフォームまで、実際の利用に耐えるシステムを構築します。",
    "about3.whatwedo.p3": "シニアエンジニアリングと固定スコープのプロセスを組み合わせることで、野心的なロードマップを納品されたソフトウェアに、そして納品されたソフトウェアを測定可能なROIに変えます。",
    "about3.whatwedo.link": "私たちの仕事の進め方を見る",
    "about3.howwedo.eyebrow": "私たちの進め方",
    "about3.howwedo.title": "スピードと明確さのためのプロセス",
    "about3.howwedo.part1.title": "まず、スコープを正しく定める",
    "about3.howwedo.part1.desc": "私たちはまずお客様のビジネス、制約、目標を理解します。構造化された調査を通じて、コードを1行も書く前に固定スコープ、スケジュール、成功指標を定義します。",
    "about3.howwedo.part2.title": "そして、構築して納品する",
    "about3.howwedo.part2.desc": "計画が固まったら、シニアエンジニアが週単位で設計・構築・デプロイを行い、各ステップで動作するソフトウェア、定期的な更新、厳格なテストを提供します。",
    "about3.howwedo.link": "私たちのプロセスについて知る",
    "about3.fit.eyebrow": "こんな方におすすめ",
    "about3.fit.title": "あなたに合っていますか？",
    "about3.fit.p1": "Technovoraは、社内チームをゼロから構築する負担なしにシニアエンジニアリングを必要とする、10〜50人規模の企業のSaaS創業者やCTOに最適です。",
    "about3.fit.p2": "明確な課題があり、実際の予算があり、四半期ではなく数週間で納品するパートナーを求めているなら、私たちはすでに同じ言葉を話しています。",
