    // --- About page: narrative sections (Phase 6 rebuild) ---
    "about3.whatwedo.eyebrow": "Wat we doen",
    "about3.whatwedo.title": "Full-stack geleverd, van begin tot eind",
    "about3.whatwedo.p1": "Technovora is een full-stack engineeringpartner voor AI-automatisering, web- en mobiele ontwikkeling, cloudinfrastructuur en design, zodat u niet vijf verschillende leveranciers aan elkaar hoeft te knopen.",
    "about3.whatwedo.p2": "We bouwen systemen die bestand zijn tegen echt gebruik, van autonome AI-agents tot productieklare platforms die zijn ontworpen voor schaal en snelheid.",
    "about3.whatwedo.p3": "Door senior engineering te combineren met een proces met een vaste scope, zetten we ambitieuze roadmaps om in geleverde software, en geleverde software in meetbare ROI.",
    "about3.whatwedo.link": "Bekijk hoe we werken",
    "about3.howwedo.eyebrow": "Hoe we het doen",
    "about3.howwedo.title": "Een proces gebouwd voor snelheid en duidelijkheid",
